/// Give the cell back if `c`.
pub fn give_if_x(c: Int) -> () {
    bc_x(c, get(l_give()))
}

pub fn next_x() -> () {
    b_x(get(l_next()))
}

/// At least `n` values on the data stack (1 or 2), else give back: tier 1
/// traps there, finding too few.
pub fn need_x(n: Int) -> () {
    if _eq(n, int_lit(1)) {
        cmp_x(x_dsp(), x_dsb());
        give_if_x(c_ls())
    } else {
        addi_x(x13(), x_dsb(), int_lit(8));
        cmp_x(x_dsp(), x13());
        give_if_x(c_ls())
    }
}

/// Room to push one, else give back (tier 1's `push!` traps).
pub fn h_room_x() -> () {
    ldr_x(x16(), x_st(), at_st(st_ds_end()));
    cmp_x(x_dsp(), x16());
    give_if_x(c_hs())
}

/// Within the limits tier 1's `check-limits!` holds to, else give back.
pub fn limits_x() -> () {
    ldr_x(x16(), x_st(), at_st(st_ds_lim()));
    cmp_x(x_dsp(), x16());
    give_if_x(c_hi());
    ldr_x(x16(), x_st(), at_st(st_rs_lim()));
    cmp_x(x_rsp(), x16());
    give_if_x(c_hs())
}

/// Two values replaced by `r`.
pub fn put_top_x(r: Int) -> () {
    subi_x(x_dsp(), x_dsp(), int_lit(8));
    stur_x(r, x_dsp(), int_lit(-8));
    next_x()
}

/// `x13` := `#t` if `c`, else `#f`.
pub fn boolean_of_x(c: Int) -> () {
    movz_x(x13(), int_lit(11));
    movz_x(x14(), int_lit(3));
    csel_x(x13(), x13(), x14(), c)
}

/// `x13` the one below the top, `x14` the top; both fixnums, else give back.
pub fn two_fixnums_x() -> () {
    need_x(int_lit(2));
    ldur_x(x13(), x_dsp(), int_lit(-16));
    ldur_x(x14(), x_dsp(), int_lit(-8));
    orr_x(x15(), x13(), x14());
    tstl_x(x15(), int_lit(3));
    give_if_x(c_ne())
}

/// `x11` the heap's address of the value in `r` plus 4; given back unless
/// it is a cellular closure: its trailer says how far back its header is,
/// the header its kind (Fixpt's `is_closure`).
pub fn closure_in_x(r: Int) -> () {
    andl_x(x13(), r, int_lit(3));
    cmpi_x(x13(), int_lit(4));
    give_if_x(c_ne());
    add_x(x11(), x_mem(), r);
    ldur_x(x15(), x11(), int_lit(-12));
    andl_x(x13(), x15(), int_lit(3));
    cmpi_x(x13(), int_lit(5));
    give_if_x(c_ne());
    sub_x(x14(), x11(), x15());
    ldur_x(x14(), x14(), int_lit(-7));
    ubfx_x(x14(), x14(), int_lit(3), int_lit(8));
    cmpi_x(x14(), i64_to_int(k_closure()));
    give_if_x(c_ne())
}

/// A call of the closure on top with the `count` values below it (tier
/// 1's `call!`), in tail position its frame slid down over this one's;
/// the count, times 8, in `x17`, which `closure-in!` keeps.
pub fn called_x(tail: bool) -> () {
    let (r#loop, done) = (label_x(), label_x());
    ldr_post_x(x17(), x_ip(), int_lit(-8));
    add_x(x14(), x_fp(), x17());
    addi_x(x14(), x14(), int_lit(8));
    cmp_x(x_dsp(), x14());
    give_if_x(c_lo());
    ldur_x(x10(), x_dsp(), int_lit(-8));
    closure_in_x(x10());
    limits_x();
    if tail {
        subi_x(x14(), x_dsp(), int_lit(8));
        sub_x(x15(), x14(), x17());
        mov_x(x16(), x_fp());
        bind_x(r#loop);
        cmp_x(x15(), x14());
        bc_x(c_hs(), done);
        ldr_post_x(x_w(), x15(), int_lit(8));
        str_post_x(x_w(), x16(), int_lit(8));
        b_x(r#loop);
        bind_x(done);
        add_x(x_dsp(), x_fp(), x17())
    } else {
        ldr_x(x16(), x_st(), at_st(st_rs_end()));
        cmp_x(x_rsp(), x16());
        give_if_x(c_hs());
        add_x(x14(), x_mem(), x_cur());
        subi_x(x14(), x14(), int_lit(4));
        sub_x(x14(), x14(), x_ip());
        sub_x(x15(), x_fp(), x_dsb());
        stp_x(x_cur(), x14(), x_rsp(), int_lit(0));
        stp_x(x15(), x_clo(), x_rsp(), int_lit(16));
        addi_x(x_rsp(), x_rsp(), int_lit(32));
        subi_x(x_dsp(), x_dsp(), int_lit(8));
        sub_x(x_fp(), x_dsp(), x17())
    };
    ldur_x(x_cur(), x11(), _minus(int_lit(-4), _star(int_lit(8), i64_to_int(f_word()))));
    mov_x(x_clo(), x10());
    add_x(x_ip(), x_mem(), x_cur());
    subi_x(x_ip(), x_ip(), _plus(int_lit(4), _star(int_lit(8), i64_to_int(f_cell0()))));
    next_x()
}

/// `x15` eight times the fields of the bloblet whose address plus 4 is in
/// `x11`, `x14` eight times the lowest that may be read: past a trailer,
/// its distance, 2; past a header, its count, 1; else given back.
pub fn fields_of_x(lowest: Int) -> () {
    let (header, done) = (label_x(), label_x());
    ldur_x(x15(), x11(), int_lit(-12));
    andl_x(x14(), x15(), int_lit(3));
    cmpi_x(x14(), int_lit(5));
    bc_x(c_ne(), header);
    subi_x(x15(), x15(), int_lit(5));
    movz_x(x14(), int_lit(16));
    b_x(done);
    bind_x(header);
    cmpi_x(x14(), int_lit(6));
    give_if_x(c_ne());
    ubfx_x(x15(), x15(), int_lit(14), int_lit(18));
    times8_x(x15());
    movz_x(x14(), int_lit(8));
    bind_x(done)
}

/// `x16` field `x13 / 8` of the bloblet at `x11`, if it may be read (tier
/// 1's `field-ok?`), else given back.
pub fn field_read_x() -> () {
    fields_of_x(int_lit(0));
    cmp_x(x13(), x14());
    give_if_x(c_lt());
    cmp_x(x13(), x15());
    give_if_x(c_hi());
    sub_x(x16(), x11(), x13());
    ldur_x(x16(), x16(), int_lit(-4))
}

/// Room for an object of `words` words more than `count8 / 8` (`count8`
/// a register, or 31 for none): `x13` the heap's `top`, `x16` its
/// address. Given back if tier 1's `safepoint!` would collect first, or
/// `room!` grow the heap.
pub fn allocating_x(words: Int, count8: Int) -> () {
    ldr_x(x13(), x_st(), at_st(st_top()));
    ldr_x(x14(), x_st(), at_st(st_alloc_limit()));
    cmp_x(x13(), x14());
    give_if_x(c_hi());
    addi_x(x15(), x13(), words);
    if _eq(count8, int_lit(31)) {
        ()
    } else {
        lsr_x(x14(), count8, int_lit(3));
        add_x(x15(), x15(), x14())
    };
    ldr_x(x14(), x_st(), at_st(st_mem_length()));
    cmp_x(x15(), x14());
    give_if_x(c_hi());
    lsl_x(x16(), x13(), int_lit(3));
    add_x(x16(), x_mem(), x16())
}

/// `cons`: the pair at the heap's top, as tier 1's `cons!` makes it.
pub fn consed_x() -> () {
    need_x(int_lit(2));
    allocating_x(int_lit(2), int_lit(31));
    ldur_x(x14(), x_dsp(), int_lit(-16));
    ldur_x(x15(), x_dsp(), int_lit(-8));
    stp_x(x14(), x15(), x16(), int_lit(0));
    addi_x(x15(), x13(), int_lit(2));
    str_x(x15(), x_st(), at_st(st_top()));
    lsl_x(x14(), x13(), int_lit(3));
    addi_x(x14(), x14(), int_lit(1));
    put_top_x(x14())
}

/// `closure W COUNT`: a cellular closure of word `W` over the `COUNT`
/// values on top, as tier 1's `make-bloblet!` lays it out: its header,
/// its fields (`count + 2`, the trailer one), its trailer.
pub fn closed_x() -> () {
    let (r#loop, done) = (label_x(), label_x());
    h_room_x();
    ldr_post_x(x10(), x_ip(), int_lit(-8));
    ldr_post_x(x17(), x_ip(), int_lit(-8));
    add_x(x14(), x_fp(), x17());
    cmp_x(x_dsp(), x14());
    give_if_x(c_lo());
    allocating_x(int_lit(3), x17());
    movz_x(x15(), _plus(int_lit(6), _star(int_lit(8), i64_to_int(k_closure()))));
    lsr_x(x14(), x17(), int_lit(3));
    addi_x(x14(), x14(), int_lit(2));
    lsl_x(x14(), x14(), int_lit(14));
    orr_x(x15(), x15(), x14());
    str_x(x15(), x16(), int_lit(0));
    add_x(x11(), x16(), x17());
    addi_x(x11(), x11(), int_lit(24));
    addi_x(x14(), x17(), int_lit(21));
    stur_x(x14(), x11(), int_lit(-8));
    stur_x(x10(), x11(), int_lit(-16));
    sub_x(x15(), x_dsp(), x17());
    subi_x(x_w(), x11(), int_lit(24));
    bind_x(r#loop);
    cmp_x(x15(), x_dsp());
    bc_x(c_hs(), done);
    ldr_post_x(x14(), x15(), int_lit(8));
    str_post_x(x14(), x_w(), int_lit(-8));
    b_x(r#loop);
    bind_x(done);
    sub_x(x_dsp(), x_dsp(), x17());
    lsr_x(x14(), x17(), int_lit(3));
    add_x(x14(), x14(), x13());
    addi_x(x14(), x14(), int_lit(3));
    str_x(x14(), x_st(), at_st(st_top()));
    sub_x(x14(), x11(), x_mem());
    addi_x(x14(), x14(), int_lit(4));
    str_post_x(x14(), x_dsp(), int_lit(8));
    next_x()
}

/// Routine number `n`'s code; what it does not do it gives back.
pub fn entered_x(n: Int) -> () {
    if _eq(n, i64_to_int(r_lit())) {
        h_room_x();
        ldr_post_x(x13(), x_ip(), int_lit(-8));
        str_post_x(x13(), x_dsp(), int_lit(8));
        next_x()
    } else if _eq(n, i64_to_int(r_dup())) {
        need_x(int_lit(1));
        h_room_x();
        ldur_x(x13(), x_dsp(), int_lit(-8));
        str_post_x(x13(), x_dsp(), int_lit(8));
        next_x()
    } else if _eq(n, i64_to_int(r_drop())) {
        need_x(int_lit(1));
        subi_x(x_dsp(), x_dsp(), int_lit(8));
        next_x()
    } else if _eq(n, i64_to_int(r_swap())) {
        need_x(int_lit(2));
        ldur_x(x13(), x_dsp(), int_lit(-8));
        ldur_x(x14(), x_dsp(), int_lit(-16));
        stur_x(x13(), x_dsp(), int_lit(-16));
        stur_x(x14(), x_dsp(), int_lit(-8));
        next_x()
    } else if _eq(n, i64_to_int(r_over())) {
        need_x(int_lit(2));
        h_room_x();
        ldur_x(x13(), x_dsp(), int_lit(-16));
        str_post_x(x13(), x_dsp(), int_lit(8));
        next_x()
    } else if _eq(n, i64_to_int(r_eq())) {
        need_x(int_lit(2));
        ldur_x(x13(), x_dsp(), int_lit(-16));
        ldur_x(x14(), x_dsp(), int_lit(-8));
        cmp_x(x13(), x14());
        boolean_of_x(c_eq());
        put_top_x(x13())
    } else if (_eq(n, i64_to_int(r_add())) || _eq(n, i64_to_int(r_int_add()))) {
        two_fixnums_x();
        adds_x(x13(), x13(), x14());
        give_if_x(c_vs());
        put_top_x(x13())
    } else if (_eq(n, i64_to_int(r_sub())) || _eq(n, i64_to_int(r_int_sub()))) {
        two_fixnums_x();
        subs_x(x13(), x13(), x14());
        give_if_x(c_vs());
        put_top_x(x13())
    } else if (_eq(n, i64_to_int(r_less())) || _eq(n, i64_to_int(r_int_less()))) {
        two_fixnums_x();
        cmp_x(x13(), x14());
        boolean_of_x(c_lt());
        put_top_x(x13())
    } else if _eq(n, i64_to_int(r_int_eq())) {
        two_fixnums_x();
        cmp_x(x13(), x14());
        boolean_of_x(c_eq());
        put_top_x(x13())
    } else if (_eq(n, i64_to_int(r_car())) || _eq(n, i64_to_int(r_cdr())) || _eq(n, i64_to_int(r_pair_car())) || _eq(n, i64_to_int(r_pair_cdr()))) {
        need_x(int_lit(1));
        ldur_x(x13(), x_dsp(), int_lit(-8));
        andl_x(x14(), x13(), int_lit(3));
        cmpi_x(x14(), int_lit(1));
        give_if_x(c_ne());
        add_x(x15(), x_mem(), x13());
        ldur_x(x16(), x15(), if (_eq(n, i64_to_int(r_car())) || _eq(n, i64_to_int(r_pair_car()))) {
            int_lit(-1)
        } else {
            int_lit(7)
        });
        stur_x(x16(), x_dsp(), int_lit(-8));
        next_x()
    } else if _eq(n, i64_to_int(r_slot())) {
        ldr_post_x(x13(), x_ip(), int_lit(-8));
        add_x(x14(), x_fp(), x13());
        cmp_x(x14(), x_dsb());
        give_if_x(c_lo());
        cmp_x(x14(), x_dsp());
        give_if_x(c_hs());
        h_room_x();
        ldr_x(x15(), x14(), int_lit(0));
        str_post_x(x15(), x_dsp(), int_lit(8));
        next_x()
    } else if _eq(n, i64_to_int(r_slot_set())) {
        need_x(int_lit(1));
        ldr_post_x(x13(), x_ip(), int_lit(-8));
        add_x(x14(), x_fp(), x13());
        subi_x(x15(), x_dsp(), int_lit(8));
        cmp_x(x14(), x_dsb());
        give_if_x(c_lo());
        cmp_x(x14(), x15());
        give_if_x(c_hs());
        ldur_x(x16(), x_dsp(), int_lit(-8));
        str_x(x16(), x14(), int_lit(0));
        mov_x(x_dsp(), x15());
        next_x()
    } else if _eq(n, i64_to_int(r_global())) {
        h_room_x();
        ldr_post_x(x13(), x_ip(), int_lit(-8));
        add_x(x14(), x_mem(), x13());
        ldur_x(x15(), x14(), _minus(int_lit(-4), _star(int_lit(8), i64_to_int(f_value()))));
        str_post_x(x15(), x_dsp(), int_lit(8));
        next_x()
    } else if _eq(n, i64_to_int(r_branch())) {
        limits_x();
        ldr_post_x(x13(), x_ip(), int_lit(-8));
        sub_x(x_ip(), x_ip(), x13());
        next_x()
    } else if _eq(n, i64_to_int(r_zbranch())) {
        let taken = label_x();
        need_x(int_lit(1));
        ldur_x(x14(), x_dsp(), int_lit(-8));
        cmpi_x(x14(), int_lit(3));
        bc_x(c_eq(), taken);
        subi_x(x_dsp(), x_dsp(), int_lit(8));
        subi_x(x_ip(), x_ip(), int_lit(8));
        next_x();
        bind_x(taken);
        limits_x();
        subi_x(x_dsp(), x_dsp(), int_lit(8));
        ldr_post_x(x13(), x_ip(), int_lit(-8));
        sub_x(x_ip(), x_ip(), x13());
        next_x()
    } else if (_eq(n, i64_to_int(r_call())) || _eq(n, i64_to_int(r_tcall()))) {
        called_x(false)
    } else if (_eq(n, i64_to_int(r_tailcall())) || _eq(n, i64_to_int(r_ttailcall()))) {
        called_x(true)
    } else if _eq(n, i64_to_int(r_free())) {
        h_room_x();
        ldr_post_x(x13(), x_ip(), int_lit(-8));
        addi_x(x13(), x13(), _star(int_lit(8), i64_to_int(f_free0())));
        andl_x(x14(), x_clo(), int_lit(3));
        cmpi_x(x14(), int_lit(4));
        give_if_x(c_ne());
        add_x(x11(), x_mem(), x_clo());
        field_read_x();
        str_post_x(x16(), x_dsp(), int_lit(8));
        next_x()
    } else if _eq(n, i64_to_int(r_field())) {
        need_x(int_lit(1));
        ldr_post_x(x13(), x_ip(), int_lit(-8));
        ldur_x(x10(), x_dsp(), int_lit(-8));
        andl_x(x14(), x10(), int_lit(3));
        cmpi_x(x14(), int_lit(4));
        give_if_x(c_ne());
        add_x(x11(), x_mem(), x10());
        field_read_x();
        stur_x(x16(), x_dsp(), int_lit(-8));
        next_x()
    } else if _eq(n, i64_to_int(r_cons())) {
        consed_x()
    } else if _eq(n, i64_to_int(r_closure())) {
        closed_x()
    } else if _eq(n, i64_to_int(r_exit())) {
        ldr_x(x16(), x_st(), at_st(st_rsb()));
        cmp_x(x_rsp(), x16());
        give_if_x(c_eq());
        b_x(get(l_pop_return()))
    } else if _eq(n, i64_to_int(r_return())) {
        need_x(int_lit(1));
        subi_x(x15(), x_dsp(), int_lit(8));
        cmp_x(x15(), x_fp());
        give_if_x(c_lo());
        ldr_x(x16(), x_st(), at_st(st_rsb()));
        cmp_x(x_rsp(), x16());
        give_if_x(c_eq());
        ldur_x(x13(), x_dsp(), int_lit(-8));
        mov_x(x_dsp(), x_fp());
        str_post_x(x13(), x_dsp(), int_lit(8));
        b_x(get(l_pop_return()))
    } else {
        b_x(get(l_give()))
    }
}

/// A jump to each routine's code, by number: routine `n`'s label is
/// `base + n`.
pub fn table_x(mut n: Int, mut base: Int) -> () {
    loop {
        if _gt_eq(n, i64_to_int(r_count())) {
            return ();
        } else {
            b_x(_plus(base, n));
            n = _plus(n, int_lit(1));
            continue;
        }
    }
}

pub fn routines_x(mut n: Int, mut base: Int) -> () {
    loop {
        if _gt_eq(n, i64_to_int(r_count())) {
            return ();
        } else {
            bind_x(_plus(base, n));
            entered_x(n);
            n = _plus(n, int_lit(1));
            continue;
        }
    }
}

/// From the native convention: the state, the heap, the data stack and
/// the return stack in `x1` to `x4`, each a flat array's suffix (tag 4).
/// Every register the machine uses kept, as Fixpt's machine keeps them.
pub fn entry_x() -> () {
    stp_pre_x(int_lit(29), int_lit(30), int_lit(31), int_lit(-96));
    stp_x(int_lit(19), int_lit(20), int_lit(31), int_lit(16));
    stp_x(int_lit(21), int_lit(22), int_lit(31), int_lit(32));
    stp_x(int_lit(23), int_lit(24), int_lit(31), int_lit(48));
    stp_x(int_lit(25), int_lit(26), int_lit(31), int_lit(64));
    stp_x(int_lit(27), int_lit(28), int_lit(31), int_lit(80));
    subi_x(x_st(), int_lit(1), int_lit(4));
    subi_x(x_mem(), int_lit(2), int_lit(4));
    subi_x(x_dsb(), int_lit(3), int_lit(4));
    subi_x(x13(), int_lit(4), int_lit(4));
    str_x(x13(), x_st(), at_st(st_rsb()));
    ldr_x(x14(), x_st(), at_st(st_ds_limit()));
    times8_x(x14());
    add_x(x14(), x_dsb(), x14());
    str_x(x14(), x_st(), at_st(st_ds_lim()));
    ldr_x(x14(), x_st(), at_st(st_rs_limit()));
    times8_x(x14());
    add_x(x14(), x13(), x14());
    str_x(x14(), x_st(), at_st(st_rs_lim()));
    ldr_x(x14(), x_st(), at_st(st_ds_length()));
    times8_x(x14());
    add_x(x14(), x_dsb(), x14());
    str_x(x14(), x_st(), at_st(st_ds_end()));
    ldr_x(x14(), x_st(), at_st(st_rs_push()));
    times8_x(x14());
    add_x(x14(), x13(), x14());
    str_x(x14(), x_st(), at_st(st_rs_end()));
    ldr_x(x_cur(), x_st(), at_st(st_cur()));
    ldr_x(x14(), x_st(), at_st(st_kk()));
    times8_x(x14());
    add_x(x_ip(), x_mem(), x_cur());
    subi_x(x_ip(), x_ip(), int_lit(4));
    sub_x(x_ip(), x_ip(), x14());
    ldr_x(x14(), x_st(), at_st(st_fp()));
    times8_x(x14());
    add_x(x_fp(), x_dsb(), x14());
    ldr_x(x_clo(), x_st(), at_st(st_clo()));
    ldr_x(x14(), x_st(), at_st(st_dsp()));
    times8_x(x14());
    add_x(x_dsp(), x_dsb(), x14());
    ldr_x(x14(), x_st(), at_st(st_rsp()));
    times8_x(x14());
    add_x(x_rsp(), x13(), x14());
    ldr_x(x_fuel(), x_st(), at_st(st_fuel()));
    next_x()
}

/// The registers back in the state, the cell being run `kk`'s, and out,
/// with `why`, a fixnum.
pub fn leave_x(why: i64) -> () {
    str_x(x_cur(), x_st(), at_st(st_cur()));
    add_x(x13(), x_mem(), x_cur());
    subi_x(x13(), x13(), int_lit(4));
    sub_x(x13(), x13(), x_cell());
    lsr_x(x13(), x13(), int_lit(3));
    str_x(x13(), x_st(), at_st(st_kk()));
    sub_x(x13(), x_fp(), x_dsb());
    lsr_x(x13(), x13(), int_lit(3));
    str_x(x13(), x_st(), at_st(st_fp()));
    str_x(x_clo(), x_st(), at_st(st_clo()));
    sub_x(x13(), x_dsp(), x_dsb());
    lsr_x(x13(), x13(), int_lit(3));
    str_x(x13(), x_st(), at_st(st_dsp()));
    ldr_x(x14(), x_st(), at_st(st_rsb()));
    sub_x(x13(), x_rsp(), x14());
    lsr_x(x13(), x13(), int_lit(3));
    str_x(x13(), x_st(), at_st(st_rsp()));
    str_x(x_fuel(), x_st(), at_st(st_fuel()));
    movz_x(int_lit(0), i64_to_int(fix(why)));
    ldp_x(int_lit(27), int_lit(28), int_lit(31), int_lit(80));
    ldp_x(int_lit(25), int_lit(26), int_lit(31), int_lit(64));
    ldp_x(int_lit(23), int_lit(24), int_lit(31), int_lit(48));
    ldp_x(int_lit(21), int_lit(22), int_lit(31), int_lit(32));
    ldp_x(int_lit(19), int_lit(20), int_lit(31), int_lit(16));
    ldp_post_x(int_lit(29), int_lit(30), int_lit(31), int_lit(96));
    ret_x()
}

// A prompt's and a mark's entries begin with these (machine.kfx's
// `prompt-mark`, `mark-mark`).
pub fn prompt_mark_word() -> i64 {
    51i64
}

pub fn mark_mark_word() -> i64 {
    43i64
}

/// The whole machine: its entry, `NEXT`, the ways out, the table, and a
/// routine for each number.
pub fn machine_x() -> () {
    let (word, table, skip, r#loop, base) = (label_x(), label_x(), label_x(), label_x(), get(hand_labels()));
    set(hand_labels(), _plus(base, i64_to_int(r_count())));
    set(l_next(), label_x());
    set(l_give(), label_x());
    set(l_give_pre(), label_x());
    set(l_ran_out(), label_x());
    set(l_pop_return(), label_x());
    entry_x();
    bind_x(get(l_next()));
    mov_x(x_cell(), x_ip());
    cbz_x(x_fuel(), get(l_give_pre()));
    subi_x(x_fuel(), x_fuel(), int_lit(1));
    ldr_post_x(x_w(), x_ip(), int_lit(-8));
    tstl_x(x_w(), int_lit(3));
    bc_x(c_ne(), word);
    cmpi_x(x_w(), _star(int_lit(8), i64_to_int(r_count())));
    give_if_x(c_hs());
    lsr_x(x10(), x_w(), int_lit(1));
    adr_x(x16(), table);
    add_x(x16(), x16(), x10());
    br_x(x16());
    bind_x(word);
    andl_x(x13(), x_w(), int_lit(3));
    cmpi_x(x13(), int_lit(4));
    give_if_x(c_ne());
    add_x(x11(), x_mem(), x_w());
    ldur_x(x10(), x11(), _minus(int_lit(-4), _star(int_lit(8), i64_to_int(f_entry()))));
    movz_x(x13(), _star(int_lit(8), i64_to_int(r_docol())));
    cmp_x(x10(), x13());
    give_if_x(c_ne());
    limits_x();
    andl_x(x13(), x_cur(), int_lit(3));
    cmpi_x(x13(), int_lit(4));
    give_if_x(c_ne());
    ldr_x(x16(), x_st(), at_st(st_rs_end()));
    cmp_x(x_rsp(), x16());
    give_if_x(c_hs());
    add_x(x13(), x_mem(), x_cur());
    subi_x(x13(), x13(), int_lit(4));
    sub_x(x13(), x13(), x_ip());
    sub_x(x14(), x_fp(), x_dsb());
    stp_x(x_cur(), x13(), x_rsp(), int_lit(0));
    stp_x(x14(), x_clo(), x_rsp(), int_lit(16));
    addi_x(x_rsp(), x_rsp(), int_lit(32));
    mov_x(x_cur(), x_w());
    subi_x(x_ip(), x11(), _plus(int_lit(4), _star(int_lit(8), i64_to_int(f_cell0()))));
    next_x();
    bind_x(get(l_give()));
    addi_x(x_fuel(), x_fuel(), int_lit(1));
    bind_x(get(l_give_pre()));
    leave_x(gave_back());
    bind_x(get(l_ran_out()));
    leave_x(ran_out());
    bind_x(get(l_pop_return()));
    bind_x(r#loop);
    ldr_x(x16(), x_st(), at_st(st_rsb()));
    cmp_x(x_rsp(), x16());
    bc_x(c_ls(), get(l_ran_out()));
    ldur_x(x13(), x_rsp(), int_lit(-32));
    cmpi_x(x13(), i64_to_int(prompt_mark_word()));
    bc_x(c_eq(), skip);
    cmpi_x(x13(), i64_to_int(mark_mark_word()));
    bc_x(c_eq(), skip);
    mov_x(x_cur(), x13());
    ldur_x(x14(), x_rsp(), int_lit(-24));
    ldur_x(x15(), x_rsp(), int_lit(-16));
    ldur_x(x_clo(), x_rsp(), int_lit(-8));
    subi_x(x_rsp(), x_rsp(), int_lit(32));
    add_x(x_ip(), x_mem(), x_cur());
    subi_x(x_ip(), x_ip(), int_lit(4));
    sub_x(x_ip(), x_ip(), x14());
    add_x(x_fp(), x_dsb(), x15());
    next_x();
    bind_x(skip);
    subi_x(x_rsp(), x_rsp(), int_lit(32));
    b_x(r#loop);
    bind_x(table);
    table_x(int_lit(0), base);
    routines_x(int_lit(0), base)
}

pub type HandCode = &'static dyn Fn(FlatArray<i64>, FlatArray<i64>, FlatArray<i64>, FlatArray<i64>) -> Int;

pub fn put4(b: &'static Bloblet<()>, at: Int, w: Int) -> () {
    bloblet_set_byte_x(b, at, modulo(w, int_lit(256)));
    bloblet_set_byte_x(b, _plus(at, int_lit(1)), modulo(quotient(w, int_lit(256)), int_lit(256)));
    bloblet_set_byte_x(b, _plus(at, int_lit(2)), modulo(quotient(w, int_lit(65536)), int_lit(256)));
    bloblet_set_byte_x(b, _plus(at, int_lit(3)), quotient(w, int_lit(16777216)))
}

/// Each instruction placed; the first that did not encode, as its place,
/// or -1.
pub fn all_put_x(mut b: &'static Bloblet<()>, mut ws: List<Int>, mut at: Int) -> Int {
    loop {
        if null_p(ws) {
            return int_lit(-1);
        } else if _lt(car(ws), int_lit(0)) {
            return quotient(at, int_lit(4));
        } else {
            put4(b, at, car(ws));
            (ws, at) = (cdr(ws), _plus(at, int_lit(4)));
            continue;
        }
    }
}

pub fn count_of(mut ws: List<Int>, mut n: Int) -> Int {
    loop {
        if null_p(ws) {
            return n;
        } else {
            (ws, n) = (cdr(ws), _plus(n, int_lit(1)));
            continue;
        }
    }
}

pub fn hand_made() -> Ref<List<HandCode>> {
    kayak_rt::kept_constant!(ONCE: Ref<List<HandCode>>);
    once(&ONCE, || {
        kayak_rt::heap_new(nil::<&'static dyn Fn(FlatArray<i64>, FlatArray<i64>, FlatArray<i64>, FlatArray<i64>) -> Int>())
    })
}

/// The machine, made once: emitted, encoded, sealed.
pub fn hand_code_x() -> &'static Sum_4made_6failed<HandCode, Str> {
    if not(null_p(get(hand_made()))) {
        kayak_rt::heap_alloc(Sum_4made_6failed::<&'static dyn Fn(FlatArray<i64>, FlatArray<i64>, FlatArray<i64>, FlatArray<i64>) -> Int, Str>::Made(car(get(hand_made()))))
    } else {
        set(hand_items(), nil::<&'static Item>());
        set(hand_labels(), int_lit(0));
        machine_x();
        let its = the::<List<&'static Item>>(reverse(get(hand_items())));
        let ws = hand_encoded(its, int_lit(0), hand_placed(its, int_lit(0), nil::<kayak_rt::value::Value>()));
        let b = the::<&'static Bloblet<()>>(make_bloblet(_star(int_lit(4), count_of(ws, int_lit(0))), ()));
        let bad = all_put_x(b, ws, int_lit(0));
        if _gt_eq(bad, int_lit(0)) {
            kayak_rt::heap_alloc(Sum_4made_6failed::<&'static dyn Fn(FlatArray<i64>, FlatArray<i64>, FlatArray<i64>, FlatArray<i64>) -> Int, Str>::Failed(string_append(str_lit("tier 2: instruction "), string_append(int_to_string(bad), str_lit(" does not encode")))))
        } else {
            let p = kayak_rt::native_procedure4::<FlatArray<i64>, FlatArray<i64>, FlatArray<i64>, FlatArray<i64>, Int>(seal_code(b));
            set(hand_made(), kayak_rt::heap_cons(p, kayak_rt::nil()));
            kayak_rt::heap_alloc(Sum_4made_6failed::<&'static dyn Fn(FlatArray<i64>, FlatArray<i64>, FlatArray<i64>, FlatArray<i64>) -> Int, Str>::Made(p))
        }
    }
}

